// This file will act as a custom wrapper for the deep-research server.
// We will import the server logic from the cloned repository and start it here.

import { Server } from "@modelcontextprotocol/sdk/server/index.js";
import { StdioServerTransport } from "@modelcontextprotocol/sdk/server/stdio.js";
import {
  CallToolRequestSchema,
  ListToolsRequestSchema,
} from "@modelcontextprotocol/sdk/types.js";

const server = new Server(
  {
    name: "custom-deep-research-server", 
    version: "0.1.0",
  },
  {
    capabilities: {
      tools: {},
    },
  }
);

// Research trigger patterns
const RESEARCH_PATTERNS = [
  /\b(research|investigate|find out|look up|search for|gather information|learn about|study|explore)\b/i,
  /\b(current|latest|recent|new|updated|modern|contemporary)\b/i,
  /\b(what is|tell me about|information about|details about|facts about)\b/i,
  /\b(compare|comparison|versus|vs|difference between|similarities)\b/i,
];

const EXTERNAL_INFO_PATTERNS = [
  /\b(news|events|statistics|data|reports|studies|trends|market|industry|technology|science)\b/i,
  /\b(who is|biography|profile|background|history of)\b/i,
  /\b(price|cost|rate|value|worth|market value)\b/i,
];

function needsResearch(text: string): boolean {
  return RESEARCH_PATTERNS.some(pattern => pattern.test(text)) ||
         EXTERNAL_INFO_PATTERNS.some(pattern => pattern.test(text));
}

async function autoResearch(queryText: string) {
  if (!needsResearch(queryText)) {
    return null;
  }

  // Mock research function - in real implementation this would call the actual deep research
  return {
    query: queryText,
    autoDetected: true,
    researchInitiated: true,
    message: "Deep research would be automatically triggered for this query"
  };
}

server.setRequestHandler(ListToolsRequestSchema, async () => ({
  tools: [
    {
      name: "deep-research",
      description: "Perform deep research on a topic using AI-powered web search",
      inputSchema: {
        type: "object",
        properties: {
          query: {
            type: "string",
            description: "The research query to investigate"
          },
          depth: {
            type: "number",
            minimum: 1,
            maximum: 5,
            description: "How deep to go in the research tree (1-5)"
          },
          breadth: {
            type: "number", 
            minimum: 1,
            maximum: 5,
            description: "How broad to make each research level (1-5)"
          }
        },
        required: ["query", "depth", "breadth"]
      }
    },
    {
      name: "auto-research-detector",
      description: "Automatically detects when research is needed and triggers deep research",
      inputSchema: {
        type: "object",
        properties: {
          text: {
            type: "string",
            description: "The text to analyze for research needs"
          }
        },
        required: ["text"]
      }
    }
  ],
}));

server.setRequestHandler(CallToolRequestSchema, async (request: any) => {
  if (request.params.name === "deep-research") {
    // This would call the actual deep research implementation
    return {
      content: [{
        type: "text",
        text: `Deep research initiated for: ${request.params.arguments.query}`
      }]
    };
  }

  if (request.params.name === "auto-research-detector") {
    const { text } = request.params.arguments as { text: string };

    const autoResult = await autoResearch(text);

    if (autoResult) {
      return {
        content: [{
          type: "text",
          text: `Auto-detected research need. Deep research would be initiated:\n\n${JSON.stringify(autoResult, null, 2)}`
        }]
      };
    } else {
      return {
        content: [{
          type: "text",
          text: "No research needed for this input."
        }]
      };
    }
  }

  return {
    content: [{
      type: "text",
      text: `Unknown tool: ${request.params.name}`
    }],
    isError: true
  };
});

async function runServer() {
  const transport = new StdioServerTransport();
  await server.connect(transport);
  console.error("Custom Deep Research MCP Server running on stdio");
}

runServer().catch((error) => {
  console.error("Fatal error running server:", error);
  process.exit(1);
});

// This file will act as a custom wrapper for the web-research server.
// We will import the server logic from the cloned repository and start it here.

import { Server } from "@modelcontextprotocol/sdk/server/index.js";
import { StdioServerTransport } from "@modelcontextprotocol/sdk/server/stdio.js";
import {
  CallToolRequestSchema,
  ListToolsRequestSchema,
} from "@modelcontextprotocol/sdk/types.js";

const server = new Server(
  {
    name: "custom-web-research-server",
    version: "0.1.0",
  },
  {
    capabilities: {
      tools: {},
    },
  }
);

// Web search trigger patterns
const WEB_SEARCH_PATTERNS = [
  /\b(search|google|find|look up|browse|web search|online|internet)\b/i,
  /\b(website|url|link|page|site|domain)\b/i,
  /\b(current events|breaking news|latest news|today's news)\b/i,
  /\b(weather|forecast|temperature|climate)\b/i,
];

const REAL_TIME_PATTERNS = [
  /\b(now|today|current|live|real-time|up to date|latest)\b/i,
  /\b(stock price|market|trading|quote|ticker)\b/i,
  /\b(schedule|timetable|hours|opening times)\b/i,
  /\b(contact|phone|address|location|directions)\b/i,
];

function needsWebSearch(text: string): boolean {
  return WEB_SEARCH_PATTERNS.some(pattern => pattern.test(text)) ||
         REAL_TIME_PATTERNS.some(pattern => pattern.test(text));
}

async function autoWebSearch(queryText: string) {
  if (!needsWebSearch(queryText)) {
    return null;
  }

  // Mock web search function - in real implementation this would call actual web search
  return {
    query: queryText,
    autoDetected: true,
    searchInitiated: true,
    message: "Web search would be automatically triggered for this query"
  };
}

server.setRequestHandler(ListToolsRequestSchema, async () => ({
  tools: [
    {
      name: "websearchGrouding",
      description: "Web grounding search tool for internet queries",
      inputSchema: {
        type: "object",
        properties: {
          query: {
            type: "string",
            description: "Search query for web grounding search"
          }
        },
        required: ["query"]
      }
    },
    {
      name: "visit_page",
      description: "Visit a webpage and extract its content",
      inputSchema: {
        type: "object",
        properties: {
          url: {
            type: "string",
            description: "URL to visit"
          },
          takeScreenshot: {
            type: "boolean",
            description: "Whether to take a screenshot"
          }
        },
        required: ["url"]
      }
    },
    {
      name: "auto-web-search-detector",
      description: "Automatically detects when web search is needed and triggers search",
      inputSchema: {
        type: "object",
        properties: {
          text: {
            type: "string",
            description: "The text to analyze for web search needs"
          }
        },
        required: ["text"]
      }
    }
  ],
}));

server.setRequestHandler(CallToolRequestSchema, async (request: any) => {
  if (request.params.name === "websearchGrouding") {
    const { query } = request.params.arguments as { query: string };

    // Implement web grounding search - for now using a placeholder
    // In production, this would call the actual neurolink websearchGrouding tool
    return {
      content: [{
        type: "text",
        text: `Web grounding search initiated for: "${query}"\n\nSearch Results:\n- Sample result 1 for "${query}"\n- Sample result 2 for "${query}"\n- Sample result 3 for "${query}"\n\nNote: This is a placeholder implementation. Replace with actual neurolink websearchGrouding integration.`
      }]
    };
  }

  if (request.params.name === "visit_page") {
    return {
      content: [{
        type: "text",
        text: `Visiting page: ${request.params.arguments.url}`
      }]
    };
  }

  if (request.params.name === "auto-web-search-detector") {
    const { text } = request.params.arguments as { text: string };

    const autoResult = await autoWebSearch(text);

    if (autoResult) {
      return {
        content: [{
          type: "text",
          text: `Auto-detected web search need. Search would be initiated:\n\n${JSON.stringify(autoResult, null, 2)}`
        }]
      };
    } else {
      return {
        content: [{
          type: "text",
          text: "No web search needed for this input."
        }]
      };
    }
  }

  return {
    content: [{
      type: "text",
      text: `Unknown tool: ${request.params.name}`
    }],
    isError: true
  };
});

async function runServer() {
  const transport = new StdioServerTransport();
  await server.connect(transport);
  console.error("Custom Web Research MCP Server running on stdio");
}

runServer().catch((error) => {
  console.error("Fatal error running server:", error);
  process.exit(1);
});

import { NeuroLink } from "@juspay/neurolink";
import { EnhancedPromptEngine } from "./src/enhanced-prompt-engine.ts";
import * as dotenv from "dotenv";
import * as readline from "readline";
import * as fs from "fs";
import * as path from "path";

// dotenv.config({ path: "../sequential-thinking/.env" });
dotenv.config();

// Create readline interface for user input
function getUserInput(prompt: string): Promise<string> {
  const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
  });

  return new Promise((resolve) => {
    rl.question(prompt, (answer) => {
      rl.close();
      resolve(answer);
    });
  });
}

// Get multi-line input for template using improved approach
function getMultiLineInput(prompt: string): Promise<string> {
  return new Promise((resolve) => {
    console.log(prompt);
    console.log("Paste your template and press Enter twice when done\n");

    const rl = readline.createInterface({
      input: process.stdin,
      output: process.stdout,
      terminal: false
    });

    let lines: string[] = [];
    let emptyLineCount = 0;
    let isComplete = false;

    // Add timeout to handle large pastes
    let timeoutId: NodeJS.Timeout;

    const finishInput = () => {
      if (isComplete) return;
      isComplete = true;

      clearTimeout(timeoutId);
      rl.close();

      const result = lines.join('\n').trim();
      console.log(`✅ Template captured (${result.length} characters)\n`);

      // Clear any remaining input from stdin buffer
      process.stdin.removeAllListeners();

      resolve(result);
    };

    rl.on('line', (line) => {
      if (isComplete) return;

      if (line.trim() === '') {
        emptyLineCount++;
        if (emptyLineCount >= 2) {
          // Two consecutive empty lines - finish input
          finishInput();
          return;
        }
      } else {
        emptyLineCount = 0;
      }

      lines.push(line);

      // Reset timeout on each line
      clearTimeout(timeoutId);
      timeoutId = setTimeout(() => {
        if (lines.length > 0 && !isComplete) {
          console.log('\n⏰ Auto-completing after timeout...');
          finishInput();
        }
      }, 2000); // 2 second timeout after last input
    });

    rl.on('close', () => {
      if (!isComplete) {
        finishInput();
      }
    });
  });
}

// Function for true real-time character-by-character streaming display
async function realTimeStreamingDisplay(content: string): Promise<void> {
  const charDelayMs = 8; // 8ms per character for smooth typewriter effect
  const punctuationDelayMs = 150; // Pause at punctuation for natural rhythm
  const punctuation = ['.', '!', '?', ';', ':'];

  for (let i = 0; i < content.length; i++) {
    const char = content[i];
    process.stdout.write(char);

    // Longer pause at punctuation for natural reading rhythm
    if (punctuation.includes(char)) {
      await new Promise(resolve => setTimeout(resolve, punctuationDelayMs));
    } else {
      await new Promise(resolve => setTimeout(resolve, charDelayMs));
    }
  }
}

// Function for word-by-word streaming display (faster alternative)
async function wordByWordStreamingDisplay(content: string): Promise<void> {
  const words = content.split(' ');
  const wordDelayMs = 40; // 40ms per word

  for (let i = 0; i < words.length; i++) {
    process.stdout.write(words[i] + ' ');
    await new Promise(resolve => setTimeout(resolve, wordDelayMs));
  }
}

// Function to save markdown file
function saveMarkdownFile(content: string, question: string): string {
  const outputDir = path.join(process.cwd(), 'output');

  // Create output directory if it doesn't exist
  if (!fs.existsSync(outputDir)) {
    fs.mkdirSync(outputDir, { recursive: true });
  }

  // Generate timestamp filename
  const timestamp = new Date().toISOString().replace(/[:.]/g, '-').split('T');
  const dateStr = timestamp[0];
  const timeStr = timestamp[1].split('.')[0];
  const filename = `response_${dateStr}_${timeStr}.md`;
  const filepath = path.join(outputDir, filename);

  // Add metadata header to the file
  const fileContent = `# AI Response

**Question:** ${question}
**Generated:** ${new Date().toISOString()}

---

${content}`;

  fs.writeFileSync(filepath, fileContent, 'utf8');
  return filepath;
}

// Interface for usage statistics
interface ToolStats {
  totalCalls: number;
  totalSteps?: number;
  totalQueries?: number;
  totalSearches?: number;
  averageSteps?: number;
  averageSearches?: number;
  averageDepth?: number;
  lastUsed: string;
}

interface UsageStats {
  lastUpdated: string;
  totalSessions: number;
  currentSession: {
    startTime: string;
    toolCalls: number;
    questions: number;
    duration?: string;
  };
  toolUsage: Record<string, ToolStats>;
}

// Function to load usage statistics
function loadUsageStats(): UsageStats {
  const statsFile = path.join(process.cwd(), 'usage-stats.json');

  if (fs.existsSync(statsFile)) {
    try {
      const data = fs.readFileSync(statsFile, 'utf8');
      return JSON.parse(data);
    } catch (error) {
      console.warn('⚠️  Error reading usage stats, creating new file');
    }
  }

  // Default stats structure
  return {
    lastUpdated: new Date().toISOString(),
    totalSessions: 0,
    currentSession: {
      startTime: new Date().toISOString(),
      toolCalls: 0,
      questions: 0
    },
    toolUsage: {}
  };
}

// Function to save usage statistics
function saveUsageStats(stats: UsageStats): void {
  const statsFile = path.join(process.cwd(), 'usage-stats.json');
  stats.lastUpdated = new Date().toISOString();

  try {
    fs.writeFileSync(statsFile, JSON.stringify(stats, null, 2), 'utf8');
  } catch (error) {
    console.error('❌ Error saving usage stats:', error);
  }
}

// Function to update tool usage
function updateToolUsage(stats: UsageStats, toolName: string, additionalSteps: number = 0): void {
  const now = new Date().toISOString();

  // Handle legacy data cleanup - convert old number entries to proper objects
  if (typeof stats.toolUsage[toolName] === 'number') {
    const oldCount = stats.toolUsage[toolName] as number;
    stats.toolUsage[toolName] = {
      totalCalls: oldCount,
      lastUsed: now
    };
  }

  if (!stats.toolUsage[toolName] || typeof stats.toolUsage[toolName] !== 'object') {
    stats.toolUsage[toolName] = {
      totalCalls: 0,
      lastUsed: now
    };
  }

  const tool = stats.toolUsage[toolName];
  tool.totalCalls++;
  tool.lastUsed = now;

  // Special handling for sequential thinking steps
  if (toolName === 'sequentialthinking') {
    if (!tool.totalSteps) tool.totalSteps = 0;
    tool.totalSteps += additionalSteps || 1; // Default to 1 step if not specified
    tool.averageSteps = tool.totalSteps / tool.totalCalls;
  }

  // Special handling for web research searches
  if (toolName === 'websearchGrounding') {
    if (!tool.totalSearches) tool.totalSearches = 0;
    tool.totalSearches += additionalSteps || 1; // Default to 1 search if not specified
    tool.averageSearches = tool.totalSearches / tool.totalCalls;
  }

  // Special handling for deep research queries (handle both possible tool names)
  if (toolName === 'deep-research' || toolName === 'deep_research' || toolName === 'deepresearch') {
    if (!tool.totalQueries) tool.totalQueries = 0;
    tool.totalQueries += additionalSteps || 1; // Default to 1 query if not specified
    tool.averageDepth = tool.totalQueries / tool.totalCalls;
  }

  stats.currentSession.toolCalls++;
}

// Function to format duration
function formatDuration(startTime: string): string {
  const start = new Date(startTime);
  const now = new Date();
  const diffMs = now.getTime() - start.getTime();
  const diffMins = Math.floor(diffMs / 60000);
  const diffSecs = Math.floor((diffMs % 60000) / 1000);
  return `${diffMins}m ${diffSecs}s`;
}

// Function to display comprehensive analytics
function displayAnalytics(stats: UsageStats): void {
  // Sequential thinking details
  const seqThinking = stats.toolUsage['sequentialthinking'];
  if (seqThinking && seqThinking.totalCalls > 0) {
    console.log(`\n📈 Sequential Thinking Details:`);
    console.log(`  🧠 Calls: ${seqThinking.totalCalls} | Steps: ${seqThinking.totalSteps || 0} | Avg: ${(seqThinking.averageSteps || 0).toFixed(1)} steps/call`);
  }

  // Web research details
  const webResearch = stats.toolUsage['websearchGrounding'];
  if (webResearch && webResearch.totalCalls > 0) {
    console.log(`\n🌐 Web Research Details:`);
    console.log(`  🔍 Calls: ${webResearch.totalCalls} | Searches: ${webResearch.totalSearches || 0} | Avg: ${(webResearch.averageSearches || 0).toFixed(1)} searches/call`);
  }

  // Deep research details
  const deepResearch = stats.toolUsage['deep-research'];
  if (deepResearch && deepResearch.totalCalls > 0) {
    console.log(`\n🔬 Deep Research Details:`);
    console.log(`  📚 Calls: ${deepResearch.totalCalls} | Queries: ${deepResearch.totalQueries || 0} | Depth: ${(deepResearch.averageDepth || 0).toFixed(1)}`);
  }
}

// Enhanced Tool Display Functions
function displayToolCallSummary(questionAnalysis: any): void {
  console.log(`🛠️  TOOLS BEING CALLED`);
  console.log(`━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━`);

  if (questionAnalysis.toolsToCall.length === 0) {
    console.log(`❌ No tools selected`);
    return;
  }

  questionAnalysis.toolsToCall.forEach((tool: string, index: number) => {
    const reason = getToolSelectionReason(tool, questionAnalysis.analysis);
    console.log(`${index + 1}. 🔧 ${getToolDisplayName(tool)}`);
    console.log(`   └─ ${reason}`);
  });

  console.log(`\n📋 Detection Summary:`);
  console.log(`   • Complex Thinking Needed: ${questionAnalysis.analysis.needsThinking ? '✅' : '❌'}`);
  console.log(`   • Web Search Needed: ${questionAnalysis.analysis.needsWebSearch ? '✅' : '❌'}`);
  console.log(`   • Research Needed: ${questionAnalysis.analysis.needsResearch ? '✅' : '❌'}`);
}

function getToolDisplayName(tool: string): string {
  const toolNames: Record<string, string> = {
    'sequentialthinking': 'Sequential Thinking AI',
    'websearchGrounding': 'Web Grounding Search Engine',
    'deep-research': 'Deep Research Analysis',
    'visit_page': 'Web Page Analyzer',
    'take_screenshot': 'Screenshot Capture Tool'
  };
  return toolNames[tool] || tool;
}

function getToolSelectionReason(tool: string, analysis: any): string {
  const reasons: Record<string, string> = {
    'sequentialthinking': analysis.isQuestion 
      ? 'Question requires structured analysis and reasoning'
      : 'Complex problem needs step-by-step thinking',
    'websearchGrounding': 'Web grounding search and research required',
    'deep-research': 'Comprehensive research and in-depth analysis required',
    'visit_page': 'Web page content analysis required'
  };
  return reasons[tool] || 'Tool selected based on input analysis';
}

async function main() {
  const neurolink = new NeuroLink({
  conversationMemory: {
    enabled: true
  },
});

  // Enhanced startup display
  console.log(`
╔══════════════════════════════════════════════════════════════╗
║                  🚀 NeuroLink AI Assistant                   ║
║                    Enhanced Test Mode                        ║
╚══════════════════════════════════════════════════════════════╝`);

  // Load persistent usage statistics
  const usageStats = loadUsageStats();
  usageStats.totalSessions++;
  usageStats.currentSession = {
    startTime: new Date().toISOString(),
    toolCalls: 0,
    questions: 0
  };

  // Get MCP status for summary
  const mcpStatus = await neurolink.getMCPStatus();
  const allTools = await neurolink.getAllAvailableTools();

  console.log(`\n Ready to automatically trigger AI tools based on your input!`);
  console.log(`\n🛠️  Available Tools:`);
  console.log(`   • 🧠 Sequential Thinking AI - Structured reasoning & analysis`);
  console.log(`   • 🌐 Google Web Search - Current information & search`);
  console.log(`   • 🔍 Deep Research Analysis - Comprehensive investigation`);
  console.log(`   • 📄 Web Page Analyzer - Content extraction & analysis`);

  console.log(`\n📊 System Status:`);
  console.log(`   • MCP Servers: ${mcpStatus.totalServers} connected`);
  console.log(`   • Available Tools: ${allTools.length} ready`);
  console.log(`   • Session #${usageStats.totalSessions}`);
  console.log(`   • Previous Tool Calls: ${Object.values(usageStats.toolUsage).reduce((sum, tool) => sum + tool.totalCalls, 0)}`);

  console.log(`\n💡 Examples to try:`);
  console.log(`   "What is quantum computing?"`);
  console.log(`   "How do neural networks work?"`);
  console.log(`   "Research the latest AI developments"`);
  console.log(`   "Compare Python vs JavaScript"`);

  console.log(`\n⚡ Commands: 'exit' or 'quit' to close, 'help' for more info`);
  console.log(`━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━`);

  let continueConversation = true;

  while (continueConversation) {
    const userQuestion = await getUserInput("Enter your question: ");

    // Check for exit commands
    const trimmedQuestion = userQuestion.trim().toLowerCase();
    if (!userQuestion.trim() || trimmedQuestion === 'exit' || trimmedQuestion === 'quit') {
      console.log("\n👋 Goodbye!");

      // Display final session analytics
      console.log("\n" + "=".repeat(50));
      console.log("📊 FINAL SESSION SUMMARY");
      console.log("=".repeat(50));
      displayAnalytics(usageStats);

      // Save final statistics
      saveUsageStats(usageStats);
      console.log(`\n💾 Session data saved to usage-stats.json`);

      continueConversation = false;
      break;
    }

    const promptEngine = new EnhancedPromptEngine();
    const questionAnalysis = promptEngine.analyzeQuestion(userQuestion);

    // Get output format template (optional)
    console.log("\nEnter output format template (or press Enter to use default markdown format):");
    console.log("(If providing template, paste it and press Enter twice when done)\n");

    const formatInput = await getUserInput("Press Enter for default, or type 'custom' to provide template: ");

    let instruction: string = '';
    let useCustomFormat = false;

    if (formatInput.trim().toLowerCase() === 'custom') {
      const outputFormat = await getMultiLineInput("\nPaste your template:");

      if (!outputFormat.trim()) {
        console.log("⚠️  No template provided. Using default format...\n");
        useCustomFormat = false;
      } else {
        useCustomFormat = true;
        instruction = `Question: ${userQuestion}

IMPORTANT: You must fill in the following template with accurate information about the question above. Replace all placeholders (text in square brackets like [TOPIC], [Description], etc.) with actual content. Maintain the exact structure and formatting of the template.

NOTE: Your response will be automatically saved as a markdown file for future reference.

Template to fill:
${outputFormat}

Fill in the template now with relevant information:`;
      }
    }

    if (!useCustomFormat) {
      instruction = promptEngine.generateOptimizedPrompt(userQuestion, questionAnalysis);
    }

    try {
      // Increment question counter
      usageStats.currentSession.questions++;

      console.log("\n▶️ [START] Step 2: Preparing AI request...");
      console.log(`🔍 [INFO] Model: gemini-2.5-pro`);
      console.log(`🔍 [INFO] Provider: vertex, Region: us-east5`);
      console.log(`🔍 [INFO] Max Tokens: 40000`);
      console.log(`🔍 [INFO] Format: ${useCustomFormat ? 'Custom template' : 'Default markdown'}`);
      console.log("✅ [DONE] Step 1: Request prepared");

      console.log(`\n▶️ [START] Step 2: Sending request to AI...`);
      console.log(`🔄 [STREAM] Starting real-time streaming response...\n`);
      const startTime = Date.now();

      let fullContent = '';
