export class AutoQuestionOrchestrator {
  private statsTracker: StatsTracker;

  constructor() {
    this.statsTracker = new StatsTracker();
  }

  // Combined question detection patterns
  private readonly QUESTION_PATTERNS = [
    /\?$/,
    /^(what|how|why|when|where|who|which|can|could|should|would|will|is|are|do|does|did)/i,
    /^(explain|describe|analyze|compare|evaluate|discuss)/i,
    /^(help|assistance|support)/i,
  ];

  private readonly COMPLEX_THINKING_PATTERNS = [
    /\b(analyze|analysis|think through|work through|reason|reasoning|logic|logical|step by step|breakdown|complex|complicated|difficult|challenging|problem|solution|strategy|approach|plan|planning|design|architect|structure)\b/i,
    /\b(compare|contrast|evaluate|assess|judge|weigh|consider|pros and cons|advantages|disadvantages|benefits|drawbacks)\b/i,
    /\b(multiple|several|various|different|alternative|options|choices|possibilities)\b/i,
  ];

  private readonly WEB_SEARCH_PATTERNS = [
    /\b(search|google|find|look up|browse|web search|online|internet)\b/i,
    /\b(website|url|link|page|site|domain)\b/i,
    /\b(current events|breaking news|latest news|today's news)\b/i,
    /\b(weather|forecast|temperature|climate)\b/i,
    /\b(now|today|current|live|real-time|up to date|latest)\b/i,
  ];

  private readonly RESEARCH_PATTERNS = [
    /\b(research|investigate|find out|look up|search for|gather information|learn about|study|explore)\b/i,
    /\b(current|latest|recent|new|updated|modern|contemporary)\b/i,
    /\b(what is|tell me about|information about|details about|facts about)\b/i,
    /\b(compare|comparison|versus|vs|difference between|similarities)\b/i,
    /\b(news|events|statistics|data|reports|studies|trends|market|industry|technology|science)\b/i,
    /\b(when is|when was|when did|when will|what year|which year)\b/i,
    /\b(where is|where was|where did|where can)\b/i,
    /\b(who is|who was|who did|who has)\b/i,
    /\b(birthday|birth date|born|age|died|death)\b/i,
    /\b(biography|biographical|life|career|achievements)\b/i,
    /\b(how old|how many|how much|what time)\b/i,
  ];

  private detectQuestion(text: string): boolean {
    return this.QUESTION_PATTERNS.some(pattern => pattern.test(text.trim()));
  }

  private needsSequentialThinking(text: string): boolean {
    return this.COMPLEX_THINKING_PATTERNS.some(pattern => pattern.test(text)) || 
           text.split(' ').length > 20 ||
           text.includes('because') || text.includes('therefore') || text.includes('however');
  }

  private needsWebSearch(text: string): boolean {
    return this.WEB_SEARCH_PATTERNS.some(pattern => pattern.test(text));
  }

  private needsResearch(text: string): boolean {
    return this.RESEARCH_PATTERNS.some(pattern => pattern.test(text));
  }

  public async processQuestion(questionText: string): Promise<{
    shouldTrigger: boolean;
    toolsToCall: string[];
    analysis: {
      isQuestion: boolean;
      needsThinking: boolean;
      needsWebSearch: boolean;
      needsResearch: boolean;
    };
    results?: any;
  }> {
    const analysis = {
      isQuestion: this.detectQuestion(questionText),
      needsThinking: this.needsSequentialThinking(questionText),
      needsWebSearch: this.needsWebSearch(questionText),
      needsResearch: this.needsResearch(questionText)
    };

    const shouldTrigger = analysis.isQuestion || analysis.needsThinking || 
                         analysis.needsWebSearch || analysis.needsResearch;

    if (!shouldTrigger) {
      return {
        shouldTrigger: false,
        toolsToCall: [],
        analysis
      };
    }

    // Determine which tools to call
    const toolsToCall = [];
    if (analysis.isQuestion || analysis.needsThinking) {
      toolsToCall.push('sequentialthinking');
    }
    if (analysis.needsWebSearch || analysis.needsResearch) {
      toolsToCall.push('websearchGrouding');
    }

    // Record the question and actual tool usage
    await this.statsTracker.recordQuestion(questionText);
    await this.statsTracker.recordToolCalls(toolsToCall);

    // Simulate calling the tools (in real implementation, these would call actual MCP tools)
    const results = await this.callAllTools(questionText, toolsToCall);

    return {
      shouldTrigger: true,
      toolsToCall: toolsToCall,
      analysis,
      results
    };
  }

  private async callAllTools(questionText: string, tools: string[]) {
    const results: any = {};

    for (const tool of tools) {
      try {
        switch (tool) {
          case 'sequentialthinking':
            results.sequentialThinking = await this.callSequentialThinking(questionText);
            break;
          case 'websearchGrouding':
            results.websearchGrouding = await this.callWebsearchGrouding(questionText);
            break;
        }
      } catch (error) {
        const errorMessage = error instanceof Error ? error.message : 'Unknown error';
        console.error(`Error calling ${tool}:`, error);
        results[tool] = { error: errorMessage };
      }
    }

    return results;
  }

  private async callSequentialThinking(question: string) {
    // This would use the MCP tool in real implementation
    return {
      tool: 'sequential-thinking',
      query: question,
      status: 'completed',
      thinking_steps: [
        `Analyzing the question: "${question}"`,
        'Breaking down the components and context',
        'Formulating a structured approach to answering'
      ]
    };
  }

  private async callWebResearch(question: string) {
    // This would use the MCP tool in real implementation
    return {
      tool: 'web-research',
      query: question,
      status: 'completed',
      search_results: [
        { url: 'example.com', title: 'Relevant search result', snippet: 'Sample content...' }
      ]
    };
  }

  private async callDeepResearch(question: string) {
    // This would use the MCP tool in real implementation
    return {
      tool: 'deep-research',
      query: question,
      status: 'completed',
      depth: 3,
      breadth: 3,
      research_tree: {
        main_query: question,
        sub_queries: ['Related aspect 1', 'Related aspect 2', 'Related aspect 3']
      }
    };
  }

  private async callWebsearchGrouding(question: string) {
    // This would use the MCP tool in real implementation
    return {
      tool: 'websearchGrouding',
      query: question,
      status: 'completed',
      search_results: [
        { 
          title: `Search result for "${question}"`,
          url: 'https://example.com/result1',
          snippet: `Relevant information about ${question} found through web grounding search...`
        },
        { 
          title: `Additional result for "${question}"`,
          url: 'https://example.com/result2',
          snippet: `More details about ${question} from web grounding search...`
        }
      ]
    };
  }

  public async getSessionStats() {
    return await this.statsTracker.getCurrentStats();
  }
}

