  return COMPLEX_THINKING_PATTERNS.some(pattern => pattern.test(text)) || 
         text.split(' ').length > 20 || // Long queries likely need structured thinking
         text.includes('because') || text.includes('therefore') || text.includes('however');
}

async function autoProcessQuestion(questionText: string) {
  if (!detectQuestion(questionText) && !needsSequentialThinking(questionText)) {
    return null;
  }

  // Automatically call sequential thinking for the question
  const result = await thinkingServer.processThought({
