function safeParseInt(value: any): number | undefined {
  if (value === undefined || value === null) {
    return undefined;
  }
  const parsed = parseInt(String(value), 10);
  return isNaN(parsed) ? undefined : parsed;
}

server.setRequestHandler(CallToolRequestSchema, async (request: any) => {
  if (request.params.name === "sequentialthinking") {
    const args = request.params.arguments as any;

    const processedArgs = {
      thought: args.thought,
      nextThoughtNeeded: args.nextThoughtNeeded ?? args.next_thought_needed,
      thoughtNumber: safeParseInt(args.thoughtNumber ?? args.thought_number),
      totalThoughts: safeParseInt(args.totalThoughts ?? args.total_thoughts),
      isRevision: args.isRevision ?? args.is_revision,
      revisesThought: safeParseInt(args.revisesThought ?? args.revises_thought),
      branchFromThought: safeParseInt(args.branchFromThought ?? args.branch_from_thought),
      branchId: args.branchId ?? args.branch_id,
      needsMoreThoughts: args.needsMoreThoughts ?? args.needs_more_thoughts,
    };

    if (processedArgs.thought === undefined) {
      processedArgs.thought = " ";
    }
    if (processedArgs.nextThoughtNeeded === undefined) {
      processedArgs.nextThoughtNeeded = true;
    }

    return thinkingServer.processThought(processedArgs);
  }

  if (request.params.name === "auto-question-analyzer") {
    const { text } = request.params.arguments as { text: string };

    const autoResult = await autoProcessQuestion(text);

    if (autoResult) {
      return {
        content: [{
          type: "text",
          text: `Auto-detected question/complex topic. Sequential thinking initiated:\n\n${JSON.stringify(autoResult, null, 2)}`
        }]
      };
    } else {
      return {
        content: [{
          type: "text",
          text: "No automatic tool calling needed for this input."
        }]
      };
    }
  }

  return {
    content: [{
      type: "text",
      text: `Unknown tool: ${request.params.name}`
    }],
    isError: true
  };
});

async function runServer() {
  const transport = new StdioServerTransport();
  await server.connect(transport);
  console.error("Custom Sequential Thinking MCP Server running on stdio");
}

runServer().catch((error) => {
  console.error("Fatal error running server:", error);
  process.exit(1);
});

