import * as fs from 'fs/promises';
import * as path from 'path';

export interface SessionStats {
  lastUpdated: string;
  totalSessions: number;
  currentSession: {
    startTime: string;
    toolCalls: number;
    questions: number;
  };
  toolUsage: Record<string, number | {
    totalCalls: number;
    lastUsed: string;
    totalSteps: number;
    averageSteps: number;
  }>;
}

export class StatsTracker {
  private statsFilePath: string;
  private stats: SessionStats | null = null;

  constructor() {
    this.statsFilePath = path.join(process.cwd(), 'usage-stats.json');
  }

  private async loadStats(): Promise<SessionStats> {
    if (this.stats) {
      return this.stats;
    }

    try {
      const data = await fs.readFile(this.statsFilePath, 'utf-8');
      this.stats = JSON.parse(data);
      return this.stats!;
    } catch (error) {
      // If file doesn't exist or is corrupted, create default stats
      this.stats = {
        lastUpdated: new Date().toISOString(),
        totalSessions: 1,
        currentSession: {
          startTime: new Date().toISOString(),
          toolCalls: 0,
          questions: 0
        },
        toolUsage: {}
      };
      await this.saveStats();
      return this.stats;
    }
  }

  private async saveStats(): Promise<void> {
    if (!this.stats) return;

    this.stats.lastUpdated = new Date().toISOString();
    await fs.writeFile(this.statsFilePath, JSON.stringify(this.stats, null, 2));
  }

  public async recordQuestion(questionText: string): Promise<void> {
    const stats = await this.loadStats();
    stats.currentSession.questions += 1;
    await this.saveStats();
  }

  public async recordToolCalls(tools: string[]): Promise<void> {
    const stats = await this.loadStats();

    // Increment total tool calls
    stats.currentSession.toolCalls += tools.length;

    // Track individual tool usage
    for (const tool of tools) {
      if (tool === 'sequentialthinking') {
        // Enhanced tracking for sequential thinking
        if (!stats.toolUsage[tool] || typeof stats.toolUsage[tool] === 'number') {
          stats.toolUsage[tool] = {
            totalCalls: 1,
            lastUsed: new Date().toISOString(),
            totalSteps: 1, // Default, would be updated with actual steps in real implementation
            averageSteps: 1
          };
        } else {
          const existingData = stats.toolUsage[tool] as any;
          existingData.totalCalls = (existingData.totalCalls || 0) + 1;
          existingData.lastUsed = new Date().toISOString();
          // Keep existing totalSteps and recalculate average
          existingData.totalSteps = existingData.totalSteps || existingData.totalCalls;
          existingData.averageSteps = existingData.totalSteps / existingData.totalCalls;
        }
      } else {
        // Simple counting for other tools
        const currentCount = stats.toolUsage[tool];
        if (typeof currentCount === 'number') {
          stats.toolUsage[tool] = currentCount + 1;
        } else {
          stats.toolUsage[tool] = 1;
        }
      }
    }

    await this.saveStats();
  }

  public async getCurrentStats(): Promise<SessionStats> {
    return await this.loadStats();
  }

  public async getFormattedStats(): Promise<string> {
    const stats = await this.loadStats();
    const sessionDuration = this.calculateSessionDuration(stats.currentSession.startTime);

    return `📊 Session Analytics:
  ⏱️  Session Duration: ${sessionDuration}
  💭 Questions Asked: ${stats.currentSession.questions}
  🔧 Total Tool Calls: ${stats.currentSession.toolCalls}

🛠️ Tool Usage Breakdown:
${Object.entries(stats.toolUsage)
  .map(([tool, count]) => {
    if (typeof count === 'number') {
      return `  • ${tool}: ${count} calls`;
    } else {
      return `  • ${tool}: ${count.totalCalls} calls (avg ${count.averageSteps.toFixed(1)} steps)`;
    }
  })
  .join('\n') || '  No tools used yet'}

📈 Session Summary:
  • Total Sessions: ${stats.totalSessions}
  • Last Updated: ${new Date(stats.lastUpdated).toLocaleString()}`;
  }

  private calculateSessionDuration(startTime: string): string {
    const start = new Date(startTime);
    const now = new Date();
    const diffMs = now.getTime() - start.getTime();

    const minutes = Math.floor(diffMs / (1000 * 60));
    const seconds = Math.floor((diffMs % (1000 * 60)) / 1000);

    if (minutes > 0) {
      return `${minutes}m ${seconds}s`;
    } else {
      return `${seconds}s`;
    }
  }

  public async startNewSession(): Promise<void> {
    const stats = await this.loadStats();
    stats.totalSessions += 1;
    stats.currentSession = {
      startTime: new Date().toISOString(),
      toolCalls: 0,
      questions: 0
    };
    await this.saveStats();
  }
}

