  SURFACE: 'surface',
  DETAILED: 'detailed',
  COMPREHENSIVE: 'comprehensive',
  EXHAUSTIVE: 'exhaustive'
} as const;

export type QuestionType = typeof QuestionType[keyof typeof QuestionType];
export type ComplexityLevel = typeof ComplexityLevel[keyof typeof ComplexityLevel];
export type DepthLevel = typeof DepthLevel[keyof typeof DepthLevel];

export interface QualityMetrics {
  minWordCount: number;
  requiredSections: string[];
  sourcesRequired: number;
  examplesRequired: number;
  citationRequired: boolean;
  technicalAccuracy: boolean;
}

export class EnhancedPromptEngine {

  /**
   * Analyzes question to determine optimal prompt strategy
   */
  public analyzeQuestion(question: string): QuestionAnalysis {
    const type = this.detectQuestionType(question);
    const complexity = this.assessComplexity(question);
    const domain = this.identifyDomain(question);
    const requiresTools = this.determineRequiredTools(question, type);
    const expectedDepth = this.determineExpectedDepth(type, complexity);
    const qualityMetrics = this.defineQualityMetrics(type, complexity, expectedDepth, requiresTools);

    return {
      type,
      complexity,
      domain,
      requiresTools,
      expectedDepth,
      qualityMetrics
    };
  }

  /**
   * Generates optimized prompt based on question analysis
   */
  public generateOptimizedPrompt(question: string, analysis: QuestionAnalysis): string {
    if (analysis.requiresTools.includes('deep-research')) {
      return `Write a comprehensive, 5,000+ word report on the following topic: "${question}"

Follow this structure:

1.  **Executive Summary:** High-level overview of the topic and findings.
2.  **Introduction:** Detailed introduction, including history and background.
3.  **Core Concepts:** Thorough explanation of core concepts, theories, and principles.
4.  **State of the Art:** Comprehensive review of the current state of the art, including recent research, news, and developments.
5.  **Applications and Use Cases:** Detailed exploration of practical applications and use cases.
6.  **Challenges and Limitations:** Critical analysis of challenges and limitations.
7.  **Future Trends:** Forward-looking analysis of future trends and directions.
8.  **Conclusion:** Summary of key findings and a concluding thought.
9.  **Bibliography:** List of all sources used.

Use a minimum of 50 credible sources (academic, industry, news). Include direct quotes, data, and code snippets, with proper citations.

**Include code blocks, tables, and flowcharts where relevant to illustrate key concepts.**

The report must be well-written, well-structured, and well-researched, suitable for publication in a professional journal.`;
    } else {
      return `Answer the following question: "${question}"`;
    }
  }

  private detectQuestionType(question: string): QuestionType {
    const q = question.toLowerCase();

    // Research patterns
    if (/\b(research|investigate|study|explore|analyze trends|market analysis|comprehensive study)\b/.test(q)) {
      return QuestionType.RESEARCH;
    }

    // Technical patterns  
    if (/\b(how to|implement|code|programming|technical|architecture|system|framework|api|algorithm)\b/.test(q)) {
      return QuestionType.TECHNICAL;
    }

    // Analytical patterns
    if (/\b(analyze|analysis|why|reasoning|logic|implications|impact|effects|consequences)\b/.test(q)) {
      return QuestionType.ANALYTICAL;
    }

    // Comparative patterns
    if (/\b(compare|versus|vs|difference|similarities|better|best|choice between|alternative)\b/.test(q)) {
      return QuestionType.COMPARATIVE;
    }

    // Current events patterns
    if (/\b(latest|current|recent|today|now|breaking|news|trends|2024|2025)\b/.test(q)) {
      return QuestionType.CURRENT_EVENTS;
    }

    // Conceptual patterns
    if (/\b(what is|explain|concept|theory|principle|understand|definition)\b/.test(q)) {
      return QuestionType.CONCEPTUAL;
    }

    // Practical patterns
    if (/\b(how to|guide|tutorial|steps|practical|application|use|apply)\b/.test(q)) {
      return QuestionType.PRACTICAL;
    }

    return QuestionType.FACTUAL;
  }

  private assessComplexity(question: string): ComplexityLevel {
    const q = question.toLowerCase();
    const wordCount = question.split(' ').length;

    // Expert level indicators
    if (/\b(architecture|enterprise|scalability|optimization|advanced|complex|sophisticated|comprehensive analysis)\b/.test(q) || wordCount > 25) {
      return ComplexityLevel.EXPERT;
    }

    // Advanced level indicators  
    if (/\b(analysis|strategy|framework|methodology|implementation|integration|performance)\b/.test(q) || wordCount > 15) {
      return ComplexityLevel.ADVANCED;
    }

    // Intermediate level indicators
    if (/\b(compare|develop|design|process|system|multiple|various)\b/.test(q) || wordCount > 8) {
      return ComplexityLevel.INTERMEDIATE;
    }

    return ComplexityLevel.BASIC;
  }

  private identifyDomain(question: string): string[] {
    const q = question.toLowerCase();
    const domains: string[] = [];

    if (/\b(technology|tech|software|programming|ai|machine learning|data science)\b/.test(q)) {
      domains.push('technology');
    }
    if (/\b(business|marketing|strategy|management|enterprise|corporate)\b/.test(q)) {
      domains.push('business');
    }
    if (/\b(science|research|academic|scientific|study|experiment)\b/.test(q)) {
      domains.push('science');
    }
    if (/\b(finance|economics|market|financial|economic|investment)\b/.test(q)) {
      domains.push('finance');
    }
    if (/\b(health|medical|healthcare|medicine|wellness)\b/.test(q)) {
      domains.push('health');
    }

    return domains.length > 0 ? domains : ['general'];
  }

  private determineRequiredTools(question: string, type: QuestionType): string[] {
    const q = question.toLowerCase();
    const tools: string[] = [];

    if (q.includes('research')) {
      tools.push('deep-research');
    }

    if (type === QuestionType.ANALYTICAL || type === QuestionType.COMPARATIVE || this.assessComplexity(question) !== ComplexityLevel.BASIC) {
        if (!tools.includes('sequentialthinking')) {
            tools.push('sequentialthinking');
        }
    }

    if (tools.length === 0) {
        tools.push('sequentialthinking');
    }

    const urlRegex = /(https?:\/\/[^\s]+)/g;
    const containsUrl = urlRegex.test(q);

    const webSearchKeywords = ['latest', 'new', 'current', 'recent', 'who is', 'what is', 'when is', 'where is'];

    if (containsUrl) {
      tools.push('visit_page');
    } else if (webSearchKeywords.some(keyword => q.includes(keyword)) || type === QuestionType.CURRENT_EVENTS || type === QuestionType.FACTUAL) {
      if (!tools.includes('websearchGrounding')) {
        tools.push('websearchGrounding');
      }
    }

    return tools;
  }

  private determineExpectedDepth(type: QuestionType, complexity: ComplexityLevel): DepthLevel {
    if (complexity === ComplexityLevel.EXPERT) return DepthLevel.EXHAUSTIVE;
    if (complexity === ComplexityLevel.ADVANCED) return DepthLevel.COMPREHENSIVE;
    if (type === QuestionType.RESEARCH) return DepthLevel.COMPREHENSIVE;
    if (complexity === ComplexityLevel.INTERMEDIATE) return DepthLevel.DETAILED;
    return DepthLevel.SURFACE;
  }

  private defineQualityMetrics(type: QuestionType, complexity: ComplexityLevel, depth: DepthLevel, tools: string[]): QualityMetrics {
    const isDeepResearch = tools.includes('deep-research');

    if (isDeepResearch) {
      return {
        minWordCount: 5000,
        requiredSections: [
          'Executive Summary',
          'Literature Review',
          'Methodology',
          'Research Findings',
          'Technical Analysis',
          'Case Studies',
          'Industry Applications',
          'Current Trends & Developments',
          'Future Implications',
          'Comparative Analysis',
          'Expert Opinions',
          'Detailed Conclusions',
          'Appendices',
          'Comprehensive Bibliography'
        ],
        sourcesRequired: 50,
        examplesRequired: 10,
        citationRequired: true,
        technicalAccuracy: true,
      };
    } else {
      return {
        minWordCount: 500,
        requiredSections: ['Detailed Summary', 'In-Depth Analysis', 'Practical Examples'],
        sourcesRequired: 3,
        examplesRequired: 2,
        citationRequired: true,
        technicalAccuracy: true,
      };
    }

    // COMPREHENSIVE HYBRID RESEARCH: Realistic but extensive web research + AI knowledge
    const baseMetrics: QualityMetrics = {
      minWordCount: 5000,  // Comprehensive research-level responses
      requiredSections: [
        'Executive Summary',
        'Literature Review',
        'Methodology',
        'Research Findings',
        'Technical Analysis',
        'Case Studies',
        'Industry Applications',
        'Current Trends & Developments',
        'Future Implications',
        'Comparative Analysis',
        'Expert Opinions',
        'Detailed Conclusions',
        'Appendices',
        'Comprehensive Bibliography'
      ],
      sourcesRequired: 50,   // Realistic web research target: 50+ actual websites
      examplesRequired: 5,   // Multiple detailed examples required
      citationRequired: true,  // MANDATORY citations with real URLs
      technicalAccuracy: true  // MANDATORY accuracy for all responses
    };

    // Adjust based on complexity - Realistic but comprehensive requirements
    switch (complexity) {
      case ComplexityLevel.EXPERT:
        baseMetrics.minWordCount = 12000;  // Extensive but achievable length
        baseMetrics.sourcesRequired = 100;  // Expert level: 100 actual web sources
        baseMetrics.examplesRequired = 10;  // Extensive examples
        break;
      case ComplexityLevel.ADVANCED:
        baseMetrics.minWordCount = 8000;   // Advanced research depth
        baseMetrics.sourcesRequired = 75;   // Advanced level: 75 web sources
        baseMetrics.examplesRequired = 8;
        break;
      case ComplexityLevel.INTERMEDIATE:
        baseMetrics.minWordCount = 6000;   // Solid research paper length
        baseMetrics.sourcesRequired = 60;   // Intermediate: 60 web sources
        baseMetrics.examplesRequired = 6;
        break;
      case ComplexityLevel.BASIC:
        baseMetrics.minWordCount = 5000;   // Still comprehensive for basic
        baseMetrics.sourcesRequired = 50;   // Basic: 50 web sources minimum
        baseMetrics.examplesRequired = 5;
        break;
    }

    // Adjust based on type
    switch (type) {
      case QuestionType.RESEARCH:
        baseMetrics.requiredSections = ['Executive Summary', 'Research Findings', 'Analysis', 'Conclusions', 'Sources'];
        baseMetrics.sourcesRequired = Math.max(baseMetrics.sourcesRequired, 3);
        baseMetrics.citationRequired = true;
        break;
      case QuestionType.TECHNICAL:
        baseMetrics.requiredSections = ['Overview', 'Technical Details', 'Implementation', 'Examples', 'Best Practices'];
        baseMetrics.examplesRequired = Math.max(baseMetrics.examplesRequired, 2);
        baseMetrics.technicalAccuracy = true;
        break;
      case QuestionType.COMPARATIVE:
        baseMetrics.requiredSections = ['Comparison Overview', 'Item A Analysis', 'Item B Analysis', 'Comparison Matrix', 'Recommendations'];
        baseMetrics.examplesRequired = Math.max(baseMetrics.examplesRequired, 2);
        break;
      case QuestionType.ANALYTICAL:
        baseMetrics.requiredSections = ['Problem Analysis', 'Key Factors', 'Implications', 'Conclusions'];
        baseMetrics.sourcesRequired = Math.max(baseMetrics.sourcesRequired, 2);
        break;
    }

    return baseMetrics;
  }

  private generateRolePrompt(analysis: QuestionAnalysis): string {
    const expertDomain = analysis.domain[0] || 'general';
    const complexityDescriptor = analysis.complexity === ComplexityLevel.EXPERT ? 'world-renowned expert' :
                                analysis.complexity === ComplexityLevel.ADVANCED ? 'senior expert' :
                                analysis.complexity === ComplexityLevel.INTERMEDIATE ? 'experienced professional' :
                                'knowledgeable specialist';

    return `🎯 ROLE: You are a ${complexityDescriptor} in ${expertDomain} with extensive knowledge and research capabilities.

EXPERTISE LEVEL: ${analysis.complexity.toUpperCase()}
QUESTION TYPE: ${analysis.type.toUpperCase()}
EXPECTED DEPTH: ${analysis.expectedDepth.toUpperCase()}

You have access to cutting-edge research tools and must provide responses that match the highest academic and professional standards in your field.`;
  }

  private generateQualityStandards(analysis: QuestionAnalysis): string {
    return `📊 QUALITY STANDARDS (MANDATORY):

✅ MINIMUM REQUIREMENTS:
• Word Count: ${analysis.qualityMetrics.minWordCount}+ words
• Required Sections: ${analysis.qualityMetrics.requiredSections.join(', ')}
• Examples: ${analysis.qualityMetrics.examplesRequired}+ practical examples
${analysis.qualityMetrics.sourcesRequired > 0 ? `• Sources: ${analysis.qualityMetrics.sourcesRequired}+ credible sources` : ''}
${analysis.qualityMetrics.citationRequired ? '• Citations: Proper citation format required' : ''}
${analysis.qualityMetrics.technicalAccuracy ? '• Technical Accuracy: Expert-level precision required' : ''}

🏆 EXCELLENCE CRITERIA:
• Clarity: Clear, well-structured, professional writing
• Depth: Comprehensive coverage of all relevant aspects  
• Accuracy: Factually correct with current information
• Practicality: Actionable insights and real-world relevance
• Innovation: Latest developments and cutting-edge insights`;
  }

  private generateToolInstructions(analysis: QuestionAnalysis): string {
    // Enhanced hybrid research combining AI knowledge with mandatory web research
    let instructions = `🛠️ ENHANCED HYBRID RESEARCH PROTOCOL (AI KNOWLEDGE + LIVE WEB RESEARCH):\n\n`;

    instructions += `🔬 MANDATORY LIVE WEB RESEARCH (ABSOLUTELY REQUIRED):
• MINIMUM 50-100 ACTUAL WEBSITES: You MUST use web research tools to visit and analyze 50-100 real websites
• REAL URL DOCUMENTATION: Every web source must include the actual URL you visited and analyzed
• COMPREHENSIVE CONTENT EXTRACTION: Extract specific facts, data, quotes, insights, AND automatically include ALL tables and code blocks found
• AUTO-INCLUDE STRUCTURED DATA: Any tables, code snippets, configuration examples, API responses, or structured data found MUST be included without user request
• PRESERVE ORIGINAL FORMATTING: Maintain exact formatting of tables and code blocks as found on source websites
• COMPREHENSIVE SOURCE DIVERSITY: Academic sites, industry reports, news articles, expert blogs, government publications, corporate websites, technical documentation, and current developments

🎯 HYBRID RESEARCH APPROACH:
  🧠 AI KNOWLEDGE FOUNDATION (60% of content):
    • Leverage your extensive training on academic papers, books, and research
    • Provide expert-level analysis and synthesis of established knowledge
    • Use your understanding for context, framework, and foundational concepts

  🌐 LIVE WEB RESEARCH (40% of content):
    • MANDATORY use of visit_page tool to research actual websites
    • Target current information, recent developments, and real-world examples
    • Validate and supplement AI knowledge with live web data
    • Gather specific URLs, dates, and current statistics

📝 ENHANCED RESEARCH METHODOLOGY:
• DUAL-SOURCE INTEGRATION: Combine AI knowledge with live web research seamlessly
• REAL CITATION TRACKING: Every web-researched fact must include [Actual URL visited]
• AUTO-CONTENT INCLUSION: Automatically include ANY tables, code blocks, configuration examples, API schemas, data structures, or technical specifications found on websites
• FORMATTING PRESERVATION: Maintain original table structures, code formatting, and technical specifications exactly as found
• COMPREHENSIVE COVERAGE: Use both knowledge sources to address ALL aspects of the question
• CURRENT VALIDATION: Use web research to validate and update AI knowledge with recent information
• STRUCTURED SYNTHESIS: Organize findings from both sources into coherent analysis

🎯 MANDATORY WEB RESEARCH REQUIREMENTS:
• TOOL USAGE: You MUST use visit_page and search tools extensively
• URL DOCUMENTATION: Provide actual URLs from websites you visit and analyze
• CONTENT INTEGRATION: Blend web-researched information with AI knowledge naturally
• CITATION FORMAT: Use [Website URL - Section/Date] for all web sources
• CURRENT INFORMATION: Prioritize recent developments and current data from web research

⚠️ CRITICAL HYBRID REQUIREMENTS:
• You CANNOT write without completing substantial web research using available tools
• Every major section must contain information from both AI knowledge AND live web research
• Your ${analysis.qualityMetrics.minWordCount}+ word response must cite actual visited websites
• Provide comprehensive bibliography with all web sources actually researched
• Balance must be maintained between AI synthesis and live web research validation`;

    return instructions;
  }

  private generateStructureTemplate(analysis: QuestionAnalysis): string {
    const sections = analysis.qualityMetrics.requiredSections;

    let template = `📋 RESPONSE STRUCTURE (MANDATORY FORMAT):\n\n`;

    sections.forEach((section, index) => {
      template += `## ${index + 1}. ${section}
[Provide comprehensive content for this section]

`;
    });

    // Add word count reminders
    template += `💡 CONTENT GUIDELINES:
• Each section should be substantial and detailed
• Use proper headings, subheadings, and formatting  
• Include bullet points, tables, or diagrams where helpful
• Maintain professional academic/business writing standards
• Total response must exceed ${analysis.qualityMetrics.minWordCount} words`;

    return template;
  }

  private generateExampleGuidance(analysis: QuestionAnalysis): string {
    return `🎯 EXAMPLE REQUIREMENTS:
• Provide ${analysis.qualityMetrics.examplesRequired}+ concrete, practical examples
• Examples must be current, relevant, and well-explained
• Include real-world applications, case studies, or scenarios
• Use specific details, numbers, and outcomes where possible
• Examples should illustrate key points and enhance understanding`;
  }

  private generateValidationCriteria(analysis: QuestionAnalysis): string {
    return `✅ FINAL VALIDATION CHECKLIST:

Before submitting your response, verify:
□ Used all required tools (${analysis.requiresTools.join(', ') || 'none'})
□ Met minimum word count (${analysis.qualityMetrics.minWordCount}+ words)
□ Included all required sections (${analysis.qualityMetrics.requiredSections.join(', ')})
□ Provided ${analysis.qualityMetrics.examplesRequired}+ practical examples
${analysis.qualityMetrics.sourcesRequired > 0 ? `□ Cited ${analysis.qualityMetrics.sourcesRequired}+ credible sources` : ''}
${analysis.qualityMetrics.citationRequired ? '□ Used proper citation format' : ''}
□ Maintained expert-level accuracy and professionalism
□ Answered the question comprehensively

🎯 SUCCESS METRIC: Your response should be publishable in a professional journal or expert publication.`;
  }
}
